class Solution {

    /**
     * @param Integer $n
     * @param Integer[] $sums
     * @return Integer[]
     */
    function recoverArray($n, $sums) {
        sort($sums);
        return $this->recover($n, $sums);
    }

    private function recover($n, $sums) {
        if ($n == 0) {
            // no elements left, sums must be [0]
            return [];
        }

        sort($sums);
        $L = count($sums);
        $x = $sums[$L-1] - $sums[$0]; // The difference between largest and smallest sum = element or -element

        // We'll try x as the element first, if fail try -x.

        // Try x
        $res = $this->tryRecover($n, $sums, $x);
        if ($res !== null) {
            return $res;
        }

        // Try -x
        $res = $this->tryRecover($n, $sums, -$x);
        return $res;
    }

    private function tryRecover($n, $sums, $x) {
        // We try to split sums into two groups:
        // sums with element x included, and sums without x included.
        // The sums with x included are sums_without_x plus x.

        $L = count($sums);
        $countMap = [];

        // Create frequency map
        foreach ($sums as $v) {
            if (!isset($countMap[$v])) {
                $countMap[$v] = 0;
            }
            $countMap[$v]++;
        }

        $sumsWithoutX = [];
        $usedMap = [];

        for ($i = 0; $i < $L; $i++) {
            $cur = $sums[$i];
            if ($countMap[$cur] == 0) continue;

            $countMap[$cur]--;
            $target = $cur + $x;
            if (!isset($countMap[$target]) || $countMap[$target] == 0) {
                // Pair not found, fail this choice of x
                // Restore count before returning
                $countMap[$cur]++;
                return null;
            }
            $countMap[$target]--;
            $sumsWithoutX[] = $cur;
        }

        $subAns = $this->recover($n - 1, $sumsWithoutX);
        if ($subAns === null) return null;

        $subAns[] = $x;
        return $subAns;
    }
}

